CREATE COLUMN TABLE "TEST_AP"."ABTN" ("ItemCode" NVARCHAR(50) NOT NULL , "SysNumber" INTEGER CS_INT NOT NULL , "DistNumber" NVARCHAR(36), "MnfSerial" NVARCHAR(36), "LotNumber" NVARCHAR(36), "ExpDate" LONGDATE CS_LONGDATE, "MnfDate" LONGDATE CS_LONGDATE, "InDate" LONGDATE CS_LONGDATE, "GrntStart" LONGDATE CS_LONGDATE, "GrntExp" LONGDATE CS_LONGDATE, "CreateDate" LONGDATE CS_LONGDATE, "Location" NVARCHAR(100), "Status" NVARCHAR(1) DEFAULT '0', "Notes" NCLOB MEMORY THRESHOLD 1000, "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "Transfered" NVARCHAR(1) DEFAULT 'N', "Instance" SMALLINT CS_INT DEFAULT 0, "AbsEntry" INTEGER CS_INT NOT NULL , "ObjType" NVARCHAR(20), "itemName" NVARCHAR(100), "LogInstanc" INTEGER CS_INT NOT NULL , "UserSign2" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, "CostTotal" DECIMAL(21,6) CS_FIXED, "Quantity" DECIMAL(21,6) CS_FIXED, "QuantOut" DECIMAL(21,6) CS_FIXED, "PriceDiff" DECIMAL(21,6) CS_FIXED, "Balance" DECIMAL(21,6) CS_FIXED, "TrackingNt" INTEGER CS_INT, "TrackiNtLn" INTEGER CS_INT, "SumDec" SMALLINT CS_INT, "U_ORIBatch" NVARCHAR(20), "U_SSCC_Status" NVARCHAR(10), "U_CreatedTime" SMALLINT CS_INT, "U_Remark" NVARCHAR(50), "U_ORIBatch_Del" NVARCHAR(20), "U_ORI_Qty_Del" DECIMAL(21,6) CS_FIXED, "U_Dis_Status" NVARCHAR(10), "U_ORIBatch_List" NVARCHAR(254), "U_Father1" NVARCHAR(50), "U_InDate_Father1" LONGDATE CS_LONGDATE, PRIMARY KEY ("AbsEntry", "LogInstanc")) UNLOAD PRIORITY 5  AUTO MERGE ;
ALTER TABLE "TEST_AP"."ABTN" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$ItemCode$DistNumber$','ItemCode','DistNumber'));
CREATE UNIQUE INDEX "ABTN_SYSTEM_KEY" ON "TEST_AP"."ABTN" ( "ItemCode" ASC, "SysNumber" ASC, "LogInstanc" ASC );
CREATE INDEX "ABTN_DIST_KEY" ON "TEST_AP"."ABTN" ( "ItemCode" ASC, "DistNumber" ASC )